# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

DAY = "09:00-17:00"

def gaps_for(worked, opening=DAY):
    spans = [parse_span(text) for text in worked]
    return find_gaps(spans, parse_span(opening))

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = gaps_for(["09:00-12:00", "13:00-17:00"])
        expected = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, expected)

    def test_gaps_at_both_ends(self):
        result = gaps_for(["10:00-11:00"], "09:00-12:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 11:00-12:00 (60 min)"
        ])

    def test_nobody_working(self):
        result = gaps_for([])
        expected = ["gap 09:00-17:00 (480 min)"]
        self.assertEqual(result, expected)

    def test_full_coverage_has_no_gaps(self):
        result = gaps_for(["09:00-13:00", "13:00-17:00"])
        self.assertEqual(result, [])

    def test_overlaps_and_order_do_not_matter(self):
        worked = [
            "14:00-16:00", "09:00-12:00", "11:00-13:00"
        ]
        self.assertEqual(gaps_for(worked), [
            "gap 13:00-14:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            gaps_for(["08:00-10:00"])

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            gaps_for(["16:00-18:00"])

if __name__ == "__main__":
    unittest.main()
